/**
 * S1 — The Problem: the old Khandala Ghat. Serpentine ghat road in safety
 * orange hugging the massif flank, instanced stalled traffic, a rockfall
 * burst, monsoon rain. Exit: the old road desaturates (ghost).
 */
import {
  BufferGeometry,
  CatmullRomCurve3,
  Group,
  Line,
  TubeGeometry,
  Vector3,
  Mesh,
  MeshBasicMaterial,
} from 'three';
import type { BuildCtx, Section } from './types';
import { GEO, makeInstanced } from './helpers';
import { mat } from '../materials/greybox';
import { heightAt } from '../world/Terrain';
import { revealInstances, type InstanceSlot } from '../utils/instanceReveal';
import { window01, easeOutCubic } from '../utils/scratch';

let ghatMat: MeshBasicMaterial;
let vehicles: ReturnType<typeof makeInstanced>;
let vehicleSlots: InstanceSlot[] = [];
let ghatCurve: CatmullRomCurve3;

export const S01_Problem: Section = {
  id: 'S01',
  title: 'The Old Ghat',
  range: [0, 0],
  cameraTrack: [
    { t: 0, pos: [520, 120, 300], look: [420, 60, 140], fov: 55 },
    { t: 0.35, pos: [420, 70, 240], look: [380, 46, 130], fov: 42 },
    { t: 0.75, pos: [340, 58, 210], look: [300, 40, 120], fov: 40, calm: true },
    { t: 1, pos: [420, 160, 340], look: [650, 20, 0], fov: 55 },
  ],
  build(ctx: BuildCtx): Group {
    const g = new Group();
    // serpentine ghat descending the flank of the short-tunnel massif (z>0 side)
    const pts: Vector3[] = [];
    for (let i = 0; i <= 14; i++) {
      const t = i / 14;
      const x = 140 + t * 320 + Math.sin(t * Math.PI * 4) * 46;
      const z = 200 - t * 110;
      pts.push(new Vector3(x, heightAt(x, z) + 1.2, z));
    }
    ghatCurve = new CatmullRomCurve3(pts);
    ghatMat = new MeshBasicMaterial({ color: 0xf26522, transparent: true, opacity: 0 });
    const tube = new Mesh(new TubeGeometry(ghatCurve, 80, 1.1, 6, false), ghatMat);
    g.add(tube);

    // outline line for legibility at distance
    const line = new Line(new BufferGeometry().setFromPoints(ghatCurve.getPoints(90)), mat.hazardLine);
    line.position.y = 0.6;
    g.add(line);

    // stalled convoy along the curve
    vehicleSlots = [];
    for (let i = 0; i < 26; i++) {
      const p = ghatCurve.getPoint(0.25 + (i / 26) * 0.5);
      vehicleSlots.push({ x: p.x, y: p.y + 0.6, z: p.z, sx: 2.6, sy: 1.1, sz: 1.2, order: i / 25 });
    }
    vehicles = makeInstanced(GEO.unitBox, mat.machine, vehicleSlots);
    g.add(vehicles);

    // rockfall + rain emitters (scrub-driven)
    const rockAt = ghatCurve.getPoint(0.45);
    ctx.particles.ensure('s1_rockfall', 'rockfall', rockAt.x, rockAt.y + 26, rockAt.z - 8, 1.6);
    ctx.particles.ensure('s1_rain', 'monsoonRain', 350, 120, 140, 2.5);
    return g;
  },
  update(localT, _dt, ctx): void {
    ctx.terrain.setMorph(1); // hold full terrain from here on
    ghatMat.opacity = 0.85 * easeOutCubic(window01(localT, 0.05, 0.3)) * (1 - window01(localT, 0.85, 1) * 0.8);
    revealInstances(vehicles, vehicleSlots, window01(localT, 0.2, 0.55), { spread: 0.3 });
    ctx.particles.scrub('s1_rockfall', window01(localT, 0.45, 0.75));
    ctx.particles.scrub('s1_rain', window01(localT, 0.1, 0.9));
  },
};
